{"type": "artifact", "title": "Simulator biaya lisensi", "summary": "Simulator biaya lisensi tahunan yang bisa digeser jumlah penggunanya.", "html": "<style>body{font:15px system-ui;margin:16px;color:#222}input{width:100%}.row{display:flex;justify-content:space-between}#out{font-size:28px;font-weight:700}</style>
<h3>Biaya lisensi per tahun</h3>
<label>Jumlah pengguna <span id="n">145</span></label>
<input id="u" type="range" min="50" max="300" value="145">
<div class="row"><span>Harga per pengguna</span><span>Rp 4.200.000</span></div>
<p id="out"></p>
<svg width="280" height="40"><rect id="bar" x="0" y="8" height="24" fill="#6669D2" rx="4"></rect></svg>
<h4>Uji segel</h4><ul id="seal"></ul>
<script>
const u=document.getElementById('u');
function draw(){const n=+u.value;document.getElementById('n').textContent=n;document.getElementById('out').textContent='Rp '+(n*4200000).toLocaleString('id-ID');document.getElementById('bar').setAttribute('width',Math.round(n/300*280));}
u.addEventListener('input',draw);draw();
const seal=document.getElementById('seal');
const say=(k,v)=>{const li=document.createElement('li');li.textContent=k+': '+v;seal.appendChild(li);};
say('jembatan aplikasi', typeof window.ReactNativeWebView==='undefined'?'tidak ada':'ADA');
say('cookie', document.cookie===''?'kosong':'TERBACA');
try{localStorage.setItem('a','1');say('localStorage','TERBUKA');}catch(e){say('localStorage','tertutup');}
fetch('https://example.com/').then(()=>say('jaringan','TERBUKA')).catch(()=>say('jaringan','diblokir'));
const w=window.open('https://example.com/');say('jendela baru', w?'TERBUKA':'diblokir');
</script>"}

